/* Complete metrics capture is independent of the plot's 1,600-point sample. */
const EXPORT_CANDIDATE_COLUMNS=['generation','candidate','elapsed_wall_seconds','collisions','mean_boundary_path_tile_lengths','max_boundary_path_tile_lengths','boundary_route_count',...Array.from({length:8},(_,i)=>'short_exit_routes_le_'+(i+1)+'_tiles'),'cached_result'];
const EXPORT_GENERATION_COLUMNS=['generation','best_so_far_collisions','generation_best_collisions','average_collisions','worst_collisions','unique_layouts','population','generations_without_improvement','elites','offspring','mutated_tiles','simulated_trials_total','reused_trials_total'];
let exportRun=null;
function beginExport(c){if(typeof markNewRun==='function')markNewRun();exportRun={config:JSON.parse(JSON.stringify(c)),startedAt:new Date().toISOString(),startedClock:performance.now(),status:'running',statusMessage:'',candidates:[],generations:[],winner:null};document.getElementById('exportNotice').textContent='Recording this experiment. Export a partial snapshot at any time.';updateExportButtons()}
function recordCandidate(m){if(typeof cacheCandidate==='function')cacheCandidate(m);if(!exportRun||!m.topology)return;let t=m.topology;exportRun.candidates.push([m.generation,m.candidate,((performance.now()-exportRun.startedClock)/1000).toFixed(3),m.score,t.meanPath,t.maxPath,t.routeCount,...t.shortCounts,m.cached?1:0].join(','));updateExportButtons()}
function recordGeneration(m){if(!exportRun)return;exportRun.generations.push([m.generation,m.best,m.generationBest,m.average,m.worst,m.unique,m.population,m.stagnant,m.elite,m.offspring,m.mutations,m.simulated,m.reused].join(','))}
function completeExport(m){if(!exportRun)return;exportRun.status='completed';exportRun.winner=JSON.parse(JSON.stringify({genome:m.genome,collisions:m.score,exits:m.exits,bins:m.bins,topology:m.topology,config:m.config,bestCollisionTrace:m.trace}));exportRun.endedAt=new Date().toISOString();document.getElementById('exportNotice').textContent=exportRun.status+' · '+exportRun.candidates.length.toLocaleString()+' candidate rows available to export.';updateExportButtons()}
function stopExport(message){if(!exportRun)return;exportRun.status=message.startsWith('Search canceled')?'canceled':'failed';exportRun.statusMessage=message;exportRun.endedAt=new Date().toISOString();document.getElementById('exportNotice').textContent=exportRun.status+' · '+exportRun.candidates.length.toLocaleString()+' candidate rows available to export.';updateExportButtons()}
function updateExportButtons(){let enabled=!!exportRun;document.getElementById('exportData').disabled=!enabled;document.getElementById('exportCsv').disabled=!enabled||!exportRun.candidates.length}
function exportCsv(columns,rows){return '\ufeff'+columns.join(',')+'\r\n'+rows.join('\r\n')+'\r\n'}
function experimentFiles(){if(!exportRun)throw Error('Start an experiment first.');const r=exportRun,shortLimit=Number(document.getElementById('shortLimit').value)||2;const settings={schema:'arcfield-export-1',engine:'C/WebAssembly compact1',application:'arcfield-multirun1',status:r.status,statusMessage:r.statusMessage,startedAt:r.startedAt,endedAt:r.endedAt||null,exportedAt:new Date().toISOString(),config:r.config,evaluatedCandidates:r.candidates.length,completedGenerations:r.generations.length,landscapeShortExitThresholdTiles:shortLimit,fitness:'minimize total particle collisions',metrics:{path:'Initial boundary-connected routes; geometric lengths in tile units.',shortExits:'Distinct undirected boundary-to-boundary routes with at most N tile visits.',collisions:'Dynamic particle trial, including collision-driven tile changes.'}};let files={'settings.json':JSON.stringify(settings,null,2)+'\n','candidate_metrics.csv':exportCsv(EXPORT_CANDIDATE_COLUMNS,r.candidates),'generation_summary.csv':exportCsv(EXPORT_GENERATION_COLUMNS,r.generations),'README.txt':`ARCFIELD EXPERIMENT EXPORT\n\nStatus: ${r.status}\nAll ${r.candidates.length} recorded candidate evaluations are included, even those omitted from the landscape sample. Repeated/cached evaluations are marked; rows are observations, not guaranteed unique layouts.\n\nFiles:\nsettings.json — experiment configuration, seed, status, and metric definitions.\ncandidate_metrics.csv — one row per evaluated candidate, including all eight short-exit thresholds. elapsed_wall_seconds is measured on the page and includes browser scheduling.\ngeneration_summary.csv — one row per completed generation. An interrupted generation can have candidate rows but no summary.\nWinner files are present only after successful completion. Intermediate candidate genomes and per-candidate time series are not retained.\n\nCSV files use UTF-8 with BOM and decimal points. Coordinates are zero-based: x increases rightward, y downward. Tile 0 connects N-E and S-W; tile 1 connects N-W and E-S; tile 2 connects N-S and E-W. Boundary routes are counted once in either direction; inaccessible internal loops are excluded. Path lengths describe starting layouts, while collisions describe the dynamic trial.\n\nThe seed/settings and winning genome preserve the experiment inputs. Exact reproduction also requires the same simulation and GA versions. The exported winner is its initial genome, rather than the collision-mutated replay layout.\n\nThis is a snapshot. Exports during a running/canceled/failed experiment may be partial. Completed experiments are also cached in this browser when storage is available. Use Load result to export an earlier run. Partial running data is in memory; export before refreshing to preserve it.\n`};
if(r.winner){let w=r.winner;files['winner.json']=JSON.stringify(w,null,2)+'\n';files['winner_tiles.csv']=exportCsv(['x','y','tile_type','tile_name'],w.genome.map((t,i)=>[i%r.config.cols,Math.floor(i/r.config.cols),t,['arc_a','arc_b','cross'][t]].join(',')));let total=0;files['winner_collisions.csv']=exportCsv(['second_start','second_end','collisions','cumulative_collisions'],w.bins.map((n,i)=>{total+=n;return[i,i+1,n,total].join(',')}))}return files}
// Standard uncompressed ZIP: no CDN dependency and readable by desktop/mobile unzip tools.
const exportCrcTable=Uint32Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0});
function zipBytes(files){let encoder=new TextEncoder(),parts=[],central=[],offset=0,centralSize=0;function header(size){let b=new Uint8Array(size);return[b,new DataView(b.buffer)]}for(let [filename,text] of Object.entries(files)){let name=encoder.encode(filename),data=encoder.encode(text),crc=0xffffffff;for(let n of data)crc=exportCrcTable[(crc^n)&255]^(crc>>>8);crc=(crc^0xffffffff)>>>0;let [local,v]=header(30+name.length);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint16(12,33,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);local.set(name,30);parts.push(local,data);let [entry,e]=header(46+name.length);e.setUint32(0,0x02014b50,true);e.setUint16(4,20,true);e.setUint16(6,20,true);e.setUint16(8,0x800,true);e.setUint16(14,33,true);e.setUint32(16,crc,true);e.setUint32(20,data.length,true);e.setUint32(24,data.length,true);e.setUint16(28,name.length,true);e.setUint32(42,offset,true);entry.set(name,46);central.push(entry);centralSize+=entry.length;offset+=local.length+data.length}let[end,v]=header(22);v.setUint32(0,0x06054b50,true);v.setUint16(8,central.length,true);v.setUint16(10,central.length,true);v.setUint32(12,centralSize,true);v.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'})}
function downloadExperiment(blob,extension){let seed=(exportRun.config.name||exportRun.config.seed).replace(/[^a-zA-Z0-9_-]/g,'-').slice(0,45)||'experiment',stamp=new Date().toISOString().replace(/[:.]/g,'-'),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`arcfield-${seed}-${stamp}.${extension}`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
document.getElementById('exportData').onclick=()=>{try{downloadExperiment(zipBytes(experimentFiles()),'zip');document.getElementById('exportNotice').textContent='Downloaded experiment ZIP · '+exportRun.candidates.length.toLocaleString()+' candidate rows · '+exportRun.status}catch(e){document.getElementById('exportNotice').textContent='Export failed: '+e.message}};
document.getElementById('exportCsv').onclick=()=>{try{downloadExperiment(new Blob([exportCsv(EXPORT_CANDIDATE_COLUMNS,exportRun.candidates)],{type:'text/csv;charset=utf-8'}),'csv');document.getElementById('exportNotice').textContent='Downloaded '+exportRun.candidates.length.toLocaleString()+' candidate rows as CSV.'}catch(e){document.getElementById('exportNotice').textContent='Export failed: '+e.message}};
